    t5_r2: "Village",
    t5_l3: "Dense buildings",
    t5_r3: "City",
    t6_title: "Getting Around in the Village",
    t6_text: "In the village, there is often no subway and the bus runs infrequently. Many journeys are therefore made by bicycle or car.",
