    t2_title: "A hatalom központjai",
    t2_text: "A városban összpontosul a közigazgatás és az oktatás. A városháza, az egyetemek és a bíróságok központi szerepet játszanak.",
    t2_h1: "Közigazgatás és tudás",
    t2_h2: "Találd meg a párokat",
