    t2_r3: "Igazságszolgáltatás",
    t3_title: "Út a munkahelyre",
    t3_text: "A városban sokan használnak tömegközlekedést a munkába járáshoz. Egy jól kiépített közlekedési hálózat nagyon fontos.",
