    t3_h2: "Lépésről lépésre",
    t3_inst: "Tedd a metrózás lépéseit a helyes sorrendbe.",
    t3_q: "Miért olyan fontos a tömegközlekedés a városokban?",
    t3_qa: "Csökkenti a dugókat és a károsanyag-kibocsátást.",
    t3_qb: "Csak turisták használják.",
