    t3_w4: "Leszállás a célnál",
    t4_title: "Szabadidő és kultúra",
    t4_text: "A városok számos lehetőséget kínálnak a szórakozásra és a kulturális fejlődésre. Színházak, múzeumok és stadionok vonzzák a látogatókat.",
