    t6_title: "Közlekedés a faluban",
    t6_text: "A faluban gyakran nincs metró, és a busz is ritkán jár. Ezért sok utat kerékpárral vagy autóval tesznek meg.",
    t6_h1: "Mobilitás vidéken",
