    t6_w4: "Felszállás a szomszédos városba tartó buszra",
    t7_title: "A faluközpont",
    t7_text: "A falu központja általában kicsi és átlátható. Egy falutér, egy templom és talán egy kisbolt alkotja a középpontot.",
    t7_h1: "Találkozóhely: Falutér",
