    t13_w2: "Die Oberfläche 'aufschneiden'",
    t13_w3: "Kontinente flach drücken",
    t13_w4: "Ebene Weltkarte erhalten",
    t14_title: "Eigenschaften von Globus und Karte",
    t14_text: "Der Globus ist ein Modell der Erde, die Karte ein flaches Abbild. Beide haben ganz bestimmte Eigenschaften.",
